<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Compras y proveedores | CampoSur</title><link rel="stylesheet" href="/assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><header class="admin-header"><div><p class="eyebrow">Abastecimiento</p><h1>Compras y proveedores</h1><p class="setup-copy">Administra proveedores y órdenes de compra de la operación.</p></div><a class="secondary-link" href="/">Volver al dashboard</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if ($success): ?><div class="setup-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Nuevo proveedor</h2><p>Registro de empresas abastecedoras</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="create_supplier"><label>Razón social<input name="business_name" required></label><label>RUT<input name="tax_id"></label><label>Contacto<input name="contact_name"></label><label>Correo<input type="email" name="email"></label><label>Teléfono<input name="phone"></label><label>Dirección<input name="address"></label><button class="primary-button" type="submit">Crear proveedor</button></form></article><article class="admin-panel"><header class="panel-header"><h2>Nueva orden de compra</h2><p>Solicitudes de abastecimiento</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="create_order"><label>Proveedor<select name="supplier_id" required><?php foreach ($supplier_options as $supplier): ?><option value="<?= (int) $supplier['id'] ?>"><?= htmlspecialchars($supplier['business_name']) ?></option><?php endforeach; ?></select></label><label>Número de orden<input name="order_number" required placeholder="OC-0001"></label><label>Fecha<input type="date" name="order_date" value="<?= date('Y-m-d') ?>" required></label><label>Temporada<select name="season_id"><option value="">Sin temporada</option><?php foreach ($season_options as $season): ?><option value="<?= (int) $season['id'] ?>"><?= htmlspecialchars($season['name']) ?></option><?php endforeach; ?></select></label><label>Fundo<select name="farm_id"><option value="">Sin fundo</option><?php foreach ($farm_options as $farm): ?><option value="<?= (int) $farm['id'] ?>"><?= htmlspecialchars($farm['name']) ?></option><?php endforeach; ?></select></label><label>Notas<input name="notes"></label><button class="primary-button" type="submit">Crear orden</button></form></article></section><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Proveedores</h2><p><?= count($suppliers) ?> registrados</p></header><div class="table-scroll"><table class="admin-table"><thead><tr><th>Empresa</th><th>RUT</th><th>Contacto</th><th>Estado</th></tr></thead><tbody><?php foreach ($suppliers as $supplier): ?><tr><td><b><?= htmlspecialchars($supplier['business_name']) ?></b><small><?= htmlspecialchars($supplier['email'] ?: 'Sin correo') ?></small></td><td><?= htmlspecialchars($supplier['tax_id'] ?: 'Sin RUT') ?></td><td><?= htmlspecialchars($supplier['contact_name'] ?: 'Sin contacto') ?></td><td><span class="status-pill status-active">Activo</span></td></tr><?php endforeach; ?></tbody></table></div></article><article class="admin-panel"><header class="panel-header"><h2>Órdenes recientes</h2><p>Seguimiento de compras</p></header><div class="role-list"><?php foreach ($orders as $order): ?><div class="role-row"><div><b><?= htmlspecialchars($order['order_number']) ?></b><small><?= htmlspecialchars($order['business_name']) ?> · <?= htmlspecialchars($order['order_date']) ?></small></div><span><?= htmlspecialchars($order['status']) ?></span></div><?php endforeach; ?></div></article></section></main></body></html>
